const std = @import("std"); const inpu = @import("ru-huma-inpu.zig"); const mock = @import("te-mock-page.zig"); const snap = @import("ru-page-snap.zig"); const fixt = @import("te-fixt-html.zig"); const T = std.testing; const pace = @import("ru-huma-pace.zig");
fn profOf(tmpz: *std.testing.TmpDir, buff: []u8) ![]const u8 { return std.fmt.bufPrint(buff, ".zig-cache/tmp/{s}/prof", .{tmpz.sub_path}); }
test "curve ends exactly on the target and has the planned step count" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); var prn = std.Random.DefaultPrng.init(3); const from: inpu.Pt = .{ .x = 10, .y = 10 }; const to: inpu.Pt = .{ .x = 410, .y = 310 }; const path = try inpu.curve(aren.allocator(), from, to, prn.random()); try T.expectEqual(@as(usize, inpu.stepsFor(from, to)), path.len); try T.expectEqual(to.x, path[path.len - 1].x); try T.expectEqual(to.y, path[path.len - 1].y); }
test "curve eases in: first hop is shorter than a middle hop" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); var prn = std.Random.DefaultPrng.init(5); const from: inpu.Pt = .{ .x = 0, .y = 0 }; const path = try inpu.curve(aren.allocator(), from, .{ .x = 600, .y = 0 }, prn.random()); const first = @abs(path[0].x - from.x) + @abs(path[0].y - from.y); const mid = path.len / 2; const midd = @abs(path[mid].x - path[mid - 1].x) + @abs(path[mid].y - path[mid - 1].y); try T.expect(first * 2.0 < midd); }
test "curve is not a straight line and differs by seed" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); var one = std.Random.DefaultPrng.init(1); var two = std.Random.DefaultPrng.init(2); const to: inpu.Pt = .{ .x = 500, .y = 0 }; const pa = try inpu.curve(aren.allocator(), .{ .x = 0, .y = 0 }, to, one.random()); const pb = try inpu.curve(aren.allocator(), .{ .x = 0, .y = 0 }, to, two.random()); var off: f64 = 0; for (pa) |pnt| off = @max(off, @abs(pnt.y)); try T.expect(off > 1.0); try T.expect(pa[3].y != pb[3].y); }
test "short or zero move still has the minimum steps" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); var prn = std.Random.DefaultPrng.init(8); const path = try inpu.curve(aren.allocator(), .{ .x = 5, .y = 5 }, .{ .x = 5, .y = 5 }, prn.random()); try T.expectEqual(@as(usize, 3), path.len); try T.expectEqual(@as(f64, 5), path[2].x); try T.expectEqual(@as(usize, 28), inpu.stepsFor(.{ .x = 0, .y = 0 }, .{ .x = 5000, .y = 0 })); }
test "plan splits ascii keys, newline and non-ascii inserts" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const ops = try inpu.planType(aren.allocator(), "hi\nbạn"); try T.expectEqual(@as(usize, 6), ops.len); try T.expect(ops[0].kind == .key); try T.expect(ops[2].kind == .ent); try T.expect(ops[4].kind == .ins); try T.expectEqualStrings("ạ", ops[4].txt); try T.expect(ops[5].kind == .key); }
test "plan drops control chars and rejects bad utf8" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const ops = try inpu.planType(aren.allocator(), "a\x01\x07b"); try T.expectEqual(@as(usize, 2), ops.len); try T.expectError(error.InvalidUtf8, inpu.planType(aren.allocator(), "\xff\xfe")); const none = try inpu.planType(aren.allocator(), ""); try T.expectEqual(@as(usize, 0), none.len); }
test "live: human click, typing with Vietnamese, trusted events, delays in range" { const gpa = T.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var mok = try mock.start(gpa, T.io, try profOf(&tmpz, &buff), fixt.chat); defer mok.stop(); var aren = std.heap.ArenaAllocator.init(gpa); defer aren.deinit(); const alo = aren.allocator(); var prn = std.Random.DefaultPrng.init(11); const rnd = prn.random(); const nodes = try snap.axSnap(alo, mok.conn); const mom = snap.findNode(nodes, "listitem", "Mom").?; var pos = try inpu.clickAt(alo, mok.conn, pace.plain(rnd), .{ .x = 5, .y = 5 }, try snap.boxCenter(alo, mok.conn, mom.bid)); try T.expectEqualStrings("Mom", try snap.evalStr(alo, mok.conn, "ch")); try T.expectEqualStrings("true", try snap.evalStr(alo, mok.conn, "String(trust.length>0 && trust.every(function(x){return x}))")); try T.expect((try std.fmt.parseInt(i32, try snap.evalStr(alo, mok.conn, "moves"), 10)) >= 3); const box = snap.findNode(nodes, "textbox", "tin nhắn").?; pos = try inpu.clickAt(alo, mok.conn, pace.plain(rnd), pos, try snap.boxCenter(alo, mok.conn, box.bid)); const t0 = std.Io.Clock.awake.now(T.io).toMilliseconds(); try inpu.typeText(alo, mok.conn, pace.plain(rnd), "Chào Mom, 7h nhé", 90, 260); const el = std.Io.Clock.awake.now(T.io).toMilliseconds() - t0; try T.expect(el >= 16 * 90); try T.expectEqualStrings("Chào Mom, 7h nhé", try snap.evalStr(alo, mok.conn, "box.innerText")); try T.expect((try std.fmt.parseInt(i32, try snap.evalStr(alo, mok.conn, "keys"), 10)) >= 8); }
test "live: scroll dispatches wheel ticks" { const gpa = T.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var mok = try mock.start(gpa, T.io, try profOf(&tmpz, &buff), "<body style='height:5000px'><div id=a>x</div>"); defer mok.stop(); var aren = std.heap.ArenaAllocator.init(gpa); defer aren.deinit(); var prn = std.Random.DefaultPrng.init(2); try inpu.scrollBy(aren.allocator(), mok.conn, pace.plain(prn.random()), .{ .x = 100, .y = 100 }, 350); const sy = try std.fmt.parseInt(i32, try snap.evalStr(aren.allocator(), mok.conn, "Math.round(window.scrollY)"), 10); try T.expect(sy >= 300 and sy <= 400); }
test "flick plan: decaying flicks that add up exactly, different each time, both directions" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const allo = aren.allocator(); var prn = std.Random.DefaultPrng.init(8); const one = try inpu.flickPlan(allo, pace.plain(prn.random()), 1500); var sum: i64 = 0; var shrink: usize = 0; for (one, 0..) |val, idx| { sum += val; if (idx > 0 and val < one[idx - 1]) shrink += 1; } try T.expectEqual(@as(i64, 1500), sum); try T.expect(shrink * 3 >= one.len * 2); const two = try inpu.flickPlan(allo, pace.plain(prn.random()), 1500); try T.expect(one.len != two.len or one[0] != two[0]); const up = try inpu.flickPlan(allo, pace.plain(prn.random()), -300); var net: i64 = 0; for (up) |val| { try T.expect(val < 0); net += val; } try T.expectEqual(@as(i64, -300), net); }
test "common digraphs are found in either case; others are not" { try T.expect(inpu.common('t', 'h')); try T.expect(inpu.common('T', 'H')); try T.expect(!inpu.common('q', 'z')); }
test "live: click lands near the center, typing rolls some keys over and keeps the text, long text is pasted" { const gpa = T.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; var mok = try mock.start(gpa, T.io, try profOf(&tmpz, &buff), "<body style='height:3000px'><button id=b style='position:absolute;left:100px;top:100px;width:80px;height:30px'>go</button>"); defer mok.stop(); var aren = std.heap.ArenaAllocator.init(gpa); defer aren.deinit(); const alo = aren.allocator(); var prn = std.Random.DefaultPrng.init(31); const hum = pace.plain(prn.random()); _ = try snap.evalStr(alo, mok.conn, "window.__e=[];window.__k=[];['pointerdown','pointerup','click'].forEach(function(n){document.addEventListener(n,function(e){__e.push(n+':'+e.clientX+','+e.clientY+':'+e.isTrusted)},true)});['keydown','keyup'].forEach(function(n){document.addEventListener(n,function(){__k.push(n==='keydown'?'d':'u')},true)})"); var pos: inpu.Pt = .{ .x = 5, .y = 5 }; var offs: usize = 0; var idx: u32 = 0; while (idx < 5) : (idx += 1) { pos = try inpu.clickAt(alo, mok.conn, hum, pos, .{ .x = 140, .y = 115 }); if (pos.x != 140 or pos.y != 115) offs += 1; try T.expect(@abs(pos.x - 140) <= 3.01 and @abs(pos.y - 115) <= 3.01); } try T.expectEqual(@as(usize, 5), offs); const evs = try snap.evalStr(alo, mok.conn, "__e.join('|')"); try T.expectEqual(@as(usize, 5), std.mem.count(u8, evs, "click:")); try T.expect(std.mem.find(u8, evs, "pointerdown") != null and std.mem.find(u8, evs, ":true") != null and std.mem.find(u8, evs, ":false") == null); const text = "the other thing in the garden is a rather nice red bike that nobody wants to ride in the rain, so then we sold it"; try inpu.typeText(alo, mok.conn, hum, text, 40, 60); const ks = try snap.evalStr(alo, mok.conn, "__k.join('')"); try T.expectEqual(text.len, std.mem.count(u8, ks, "d")); try T.expectEqual(text.len, std.mem.count(u8, ks, "u")); try T.expect(std.mem.find(u8, ks, "dd") != null); try T.expect(std.mem.count(u8, ks, "dd") * 100 < text.len * 40); var long: [300]u8 = undefined; @memset(&long, 'a'); _ = try snap.evalStr(alo, mok.conn, "window.__k=[];0"); try inpu.typeText(alo, mok.conn, hum, &long, 40, 60); try T.expectEqualStrings("", try snap.evalStr(alo, mok.conn, "__k.join('')")); }
